using System;using System.IO;using System.Linq;using System.Reflection;using UnityEditor;using UnityEngine;using MashBoxSDK.AnimationStudio;using Object=UnityEngine.Object;
public static class StudioGridTexturePreviewValidation {
 const BindingFlags F=BindingFlags.Instance|BindingFlags.Static|BindingFlags.NonPublic|BindingFlags.Public;static int checks;static StudioModelEditor ed;
 static void Check(bool b,string m){checks++;if(!b)throw new Exception(m);}
 static object Call(string n,params object[] a)=>typeof(StudioModelEditor).GetMethods(F).Single(m=>m.Name==n&&m.GetParameters().Length==a.Length).Invoke(ed,a);
 static Color32[] Draw(Material material,Mesh mesh,string name){var rt=new RenderTexture(512,512,24);rt.Create();var old=RenderTexture.active;var cam=new GameObject("Preview validation camera").AddComponent<Camera>();cam.transform.position=new Vector3(0,0,-3);cam.orthographic=true;cam.orthographicSize=1.2f;cam.targetTexture=rt;var texture=new Texture2D(512,512,TextureFormat.RGBA32,false);GL.PushMatrix();try{Shader.SetGlobalVector("_WorldSpaceCameraPos",cam.transform.position);RenderTexture.active=rt;GL.Clear(true,true,Color.black);GL.LoadProjectionMatrix(Matrix4x4.Ortho(-1.2f,1.2f,-1.2f,1.2f,-10,10));GL.modelview=Matrix4x4.identity;material.SetInt("_Cull",0);material.SetFloat("_BlackBackfaces",0);Check(material.SetPass(0),"Preview shader pass unavailable");Graphics.DrawMeshNow(mesh,Matrix4x4.identity);texture.ReadPixels(new Rect(0,0,512,512),0,0);texture.Apply();File.WriteAllBytes(Out(name),texture.EncodeToPNG());return texture.GetPixels32();}finally{GL.PopMatrix();RenderTexture.active=old;Object.DestroyImmediate(texture);Object.DestroyImmediate(rt);Object.DestroyImmediate(cam.gameObject);}}
 static string Out(string n)=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../"+n));
 public static void Run(){EditorApplication.delayCall+=()=>{string result;try{ShaderUtil.allowAsyncCompilation=false;AssetDatabase.ImportAsset("Assets/Editor/MashBoxStudio_Prototype_Modeling_Shader.shadergraph",ImportAssetOptions.ForceSynchronousImport);var shader=AssetDatabase.LoadAssetAtPath<Shader>("Assets/Editor/MashBoxStudio_Prototype_Modeling_Shader.shadergraph");Check(shader,"Prototype shader not imported");var source=new Material(shader);string baseProperty=source.HasTexture("_GridTexture")?"_GridTexture":source.HasTexture("_BaseMap")?"_BaseMap":"_BaseColorMap";Check(source.HasTexture(baseProperty),"Actual prototype graph lacks a base texture");var grid=new Texture2D(2,2,TextureFormat.RGBA32,false,true);grid.filterMode=FilterMode.Point;grid.SetPixels(new[]{Color.red,Color.blue,Color.blue,Color.red});grid.Apply();source.SetTexture(baseProperty,grid);source.SetColor("_Color",Color.white);source.SetTextureScale(baseProperty,new Vector2(2,3));source.SetTextureOffset(baseProperty,new Vector2(.1f,.2f));var mesh=new Mesh();mesh.vertices=new[]{new Vector3(-1,-1,0),new Vector3(1,-1,0),new Vector3(1,1,0),new Vector3(-1,1,0)};mesh.uv=new[]{Vector2.zero,Vector2.right,Vector2.one,Vector2.up};mesh.triangles=new[]{0,1,2,0,2,3};mesh.RecalculateNormals();mesh.RecalculateBounds();var doc=ScriptableObject.CreateInstance<StudioModelDocument>();doc.nodes.Add(new StudioModelDocument.Node{mesh=mesh,materials=new[]{source},cutPolygons=new[]{0,4,0,1,2,3},cutTriangles=mesh.triangles});ed=new StudioModelEditor(()=>{});ed.Load(doc);ed.SetCheckerMap(false);ed.SetXRayMode(false);
 foreach(bool light in new[]{false}){ed.SetDisplayMode(light,true);var preview=ed.Transforms[0].GetComponent<Renderer>().sharedMaterial;Check(preview.GetTexture("_MainTex")==grid,"GridTexture not mapped");Check(preview.GetTextureScale("_MainTex")==new Vector2(2,3)&&preview.GetTextureOffset("_MainTex")==new Vector2(.1f,.2f),"Tiling/offset lost");var pixels=Draw(preview,mesh,"grid-preview-"+(light?"camera":"unlit")+".png");Check(pixels.Count(p=>p.r>30&&p.r>p.b*2)>1000,"Red grid cells absent");Check(pixels.Count(p=>p.b>30&&p.b>p.r*2)>1000,"Blue grid cells absent");}
 ed.SetXRayMode(true);var xray=ed.Transforms[0].GetComponent<Renderer>().sharedMaterial;Check(xray.GetTexture("_MainTex")==grid,"Xray lost grid map");Check(doc.nodes[0].materials[0]==source&&source.GetTexture(baseProperty)==grid,"Source material assignment mutated");var semantic=new Material(Shader.Find("Hidden/StudioTest/MainTexture"));semantic.SetTexture("_CustomAlbedo",grid);semantic.SetTexture("_BaseMap",Texture2D.whiteTexture);Check((string)Call("PreviewBaseTextureProperty",semantic)=="_CustomAlbedo","MainTexture designation not preferred");var legacy=new Material(Shader.Find("Unlit/Texture"));legacy.mainTexture=grid;Check((string)Call("PreviewBaseTextureProperty",legacy)=="_MainTex","Legacy MainTex fallback regressed");result="PASS "+checks+" actual prototype graph texture mapping, tiling/offset, camera/unlit rendered cells, Xray, semantic property and source-preservation checks";
 }catch(Exception e){result=e.ToString();}finally{ed?.Dispose();}File.WriteAllText(Out("grid-preview-result.txt"),result);EditorApplication.Exit(result.StartsWith("PASS")?0:1);};}
}
